#### Variation 3: Event Sourcing with CQRS

**Scenario**: Complete audit trail required; need to reconstruct state from event history

**Implementation**:

```csharp
// Events represent state transitions, not current state
public abstract record ClaimEvent
{
    public string EventId { get; init; }
    public string ClaimId { get; init; }
    public DateTime OccurredAt { get; init; }
    public int Version { get; init; }
}

public record ClaimSubmitted : ClaimEvent
{
    public string ProviderId { get; init; }
    public string MemberId { get; init; }
    public DateTime ServiceDate { get; init; }
    public decimal BilledAmount { get; init; }
}

public record ClaimApproved : ClaimEvent
{
    public decimal ApprovedAmount { get; init; }
    public string ApprovalReason { get; init; }
}

public record ClaimPaid : ClaimEvent
{
    public decimal PaidAmount { get; init; }
    public DateTime PaymentDate { get; init; }
    public string CheckNumber { get; init; }
}

// Claim aggregate reconstructed from events
public class Claim
{
    public string ClaimId { get; private set; }
    public ClaimStatus Status { get; private set; }
    public decimal BilledAmount { get; private set; }
    public decimal ApprovedAmount { get; private set; }
    public decimal PaidAmount { get; private set; }

    private List<ClaimEvent> _events = new();

    // Reconstruct state from event history
    public static Claim FromHistory(IEnumerable<ClaimEvent> history)
    {
        var claim = new Claim();
        foreach (var evt in history.OrderBy(e => e.Version))
        {
            claim.Apply(evt);
        }
        return claim;
    }

    private void Apply(ClaimEvent evt)
    {
        switch (evt)
        {
            case ClaimSubmitted submitted:
                ClaimId = submitted.ClaimId;
                Status = ClaimStatus.Submitted;
                BilledAmount = submitted.BilledAmount;
                break;
            case ClaimApproved approved:
                Status = ClaimStatus.Approved;
                ApprovedAmount = approved.ApprovedAmount;
                break;
            case ClaimPaid paid:
                Status = ClaimStatus.Paid;
                PaidAmount = paid.PaidAmount;
                break;
        }
    }
}

// Query model projection (CQRS read side)
public class ClaimProjectionConsumer : IConsumer<ClaimEvent>
{
    private readonly IClaimReadRepository _readRepo;

    public async Task Consume(ConsumeContext<ClaimEvent> context)
    {
        var evt = context.Message;

        // Update denormalized read model for queries
        await _readRepo.UpdateClaimProjectionAsync(evt);
    }
}
```

**When to Use**:
- Complete audit trail required for regulatory compliance (HIPAA, state audits)
- Need to replay events to rebuild state after bugs or data corruption
- Temporal queries required (\"what was claim status on March 15?\")
- Complex business workflows with many state transitions

**Trade-offs**:
- **Pros**: Complete audit history; can replay to any point in time; supports complex business workflows; eliminates data loss
- **Cons**: Higher complexity; requires separate read models (CQRS); event schema evolution challenging; storage costs for complete history

