**Step 2: Define Event Schema Standards**

```csharp
// Base event interface for all domain events
public interface IDomainEvent
{
    string EventId { get; }
    string EventType { get; }
    DateTime OccurredAt { get; }
    string CorrelationId { get; }
    string CausationId { get; }
    int Version { get; }
}

// Example event with CloudEvents standard
public record ClaimSubmittedEvent : IDomainEvent
{
    // CloudEvents standard fields
    public string EventId { get; init; } = Guid.NewGuid().ToString();
    public string EventType { get; init; } = \"com.gainwell.claims.submitted.v1\";
    public DateTime OccurredAt { get; init; } = DateTime.UtcNow;
    public string Source { get; init; } = \"/claims-api\";
    public string CorrelationId { get; init; }  // Track request across services
    public string CausationId { get; init; }  // Event that caused this event
    public int Version { get; init; } = 1;

    // Domain-specific payload
    public ClaimData Data { get; init; }
}

public record ClaimData
{
    public string ClaimId { get; init; }
    public string ProviderId { get; init; }
    public string MemberId { get; init; }
    public DateTime ServiceDate { get; init; }
    public string ServiceCode { get; init; }
    public decimal BilledAmount { get; init; }
    public string State { get; init; }  // Partition key
}

// Register schema with Schema Registry
public class SchemaRegistryConfig
{
    public async Task RegisterSchemasAsync()
    {
        var schemaRegistry = new CachedSchemaRegistryClient(new SchemaRegistryConfig
        {
            Url = \"https://gainwell-schema-registry.azure.net\"
        });

        var claimSubmittedSchema = await File.ReadAllTextAsync(\"schemas/claim-submitted-v1.avsc\");
        await schemaRegistry.RegisterSchemaAsync(
            \"com.gainwell.claims.submitted-value\",
            claimSubmittedSchema);
