**Step 3: Implement Event Producer**

```csharp
public class ClaimsService
{
    private readonly IEventPublisher _eventPublisher;
    private readonly IClaimRepository _repository;

    public async Task<string> SubmitClaimAsync(ClaimRequest request)
    {
        // 1. Validate and persist claim
        var claim = Claim.Create(request);
        await _repository.SaveAsync(claim);

        // 2. Publish domain event
        var evt = new ClaimSubmittedEvent
        {
            CorrelationId = Activity.Current?.Id ?? Guid.NewGuid().ToString(),
            Data = new ClaimData
            {
                ClaimId = claim.Id,
                ProviderId = request.ProviderId,
                MemberId = request.MemberId,
                ServiceDate = request.ServiceDate,
                ServiceCode = request.ServiceCode,
                BilledAmount = request.BilledAmount,
                State = request.State  // Used for partitioning
            }
        };

        await _eventPublisher.PublishAsync(
            topic: \"claims.submitted\",
            evt: evt,
            partitionKey: evt.Data.State);  // Partition by state for ordering

        return claim.Id;
    }
}

// Event publisher implementation using MassTransit
public class MassTransitEventPublisher : IEventPublisher
{
    private readonly IPublishEndpoint _publishEndpoint;

    public async Task PublishAsync<T>(string topic, T evt, string partitionKey) where T : IDomainEvent
    {
        await _publishEndpoint.Publish(evt, context =>
        {
            context.Headers.Set(\"PartitionKey\", partitionKey);
            context.MessageId = Guid.Parse(evt.EventId);
            context.CorrelationId = Guid.Parse(evt.CorrelationId);
        });
    }
}
```

**Step 4: Implement Event Consumer**

```csharp
// Consumer with idempotency and error handling
public class ClaimSubmittedConsumer : IConsumer<ClaimSubmittedEvent>
{
    private readonly IEligibilityService _eligibilityService;
    private readonly IProcessedEventStore _processedEvents;
    private readonly ILogger<ClaimSubmittedConsumer> _logger;

    public async Task Consume(ConsumeContext<ClaimSubmittedEvent> context)
    {
        var evt = context.Message;

        // Idempotency check - have we processed this event before?
        if (await _processedEvents.HasProcessedAsync(evt.EventId))
        {
            _logger.LogInformation(\"Event {EventId} already processed, skipping\", evt.EventId);
            return;
        }

        try
        {
            // Process event
            var result = await _eligibilityService.VerifyEligibilityAsync(
                evt.Data.MemberId,
                evt.Data.ServiceDate);

            // Publish result event
            await context.Publish(new EligibilityVerifiedEvent
            {
                CorrelationId = evt.CorrelationId,
                CausationId = evt.EventId,
                Data = new EligibilityData
                {
                    ClaimId = evt.Data.ClaimId,
                    MemberId = evt.Data.MemberId,
                    IsEligible = result.IsEligible,
                    CoverageType = result.CoverageType,
                    VerifiedAt = DateTime.UtcNow
                }
            });

            // Record that we've processed this event
            await _processedEvents.MarkProcessedAsync(evt.EventId, DateTime.UtcNow);

            _logger.LogInformation(
                \"Processed ClaimSubmitted event {EventId} for claim {ClaimId}\",
                evt.EventId,
                evt.Data.ClaimId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                \"Error processing ClaimSubmitted event {EventId}\",
                evt.EventId);

            // MassTransit will retry based on retry policy
            // After exhausting retries, moves to error queue
            throw;
        }
    }
}

// Consumer configuration with retry policy
public class ConsumerConfiguration : IHostedService
{
    public void ConfigureBus(IBusRegistrationConfigurator configurator)
    {
        configurator.AddConsumer<ClaimSubmittedConsumer>(config =>
        {
            config.UseMessageRetry(r =>
            {
                r.Exponential(5,
                    TimeSpan.FromSeconds(1),
                    TimeSpan.FromSeconds(30),
                    TimeSpan.FromSeconds(5));
            });

            config.UseInMemoryOutbox();  // Ensures exactly-once message handling
        });
    }
}
```

