**Step 2: Implement Saga Pattern for Complex Workflows**

```csharp
// Saga state machine for claim processing workflow
public class ClaimProcessingSaga : MassTransitStateMachine<ClaimSagaState>
{
    public ClaimProcessingSaga()
    {
        InstanceState(x => x.CurrentState);

        Event(() => ClaimSubmitted, x => x.CorrelateById(m => m.Message.Data.ClaimId));
        Event(() => EligibilityVerified, x => x.CorrelateById(m => m.Message.Data.ClaimId));
        Event(() => FraudCheckCompleted, x => x.CorrelateById(m => m.Message.Data.ClaimId));
        Event(() => PriorAuthVerified, x => x.CorrelateById(m => m.Message.Data.ClaimId));

        Initially(
            When(ClaimSubmitted)
                .Then(context =>
                {
                    context.Saga.ClaimId = context.Message.Data.ClaimId;
                    context.Saga.SubmittedAt = context.Message.OccurredAt;
                    context.Saga.CorrelationId = context.Message.CorrelationId;
                })
                .TransitionTo(VerifyingEligibility)
                // Kick off parallel verification checks
                .PublishAsync(context => context.Init<VerifyEligibilityCommand>(new
                {
                    ClaimId = context.Saga.ClaimId,
                    MemberId = context.Message.Data.MemberId
                }))
                .PublishAsync(context => context.Init<RunFraudCheckCommand>(new
                {
                    ClaimId = context.Saga.ClaimId,
                    ProviderId = context.Message.Data.ProviderId
                }))
                .PublishAsync(context => context.Init<VerifyPriorAuthCommand>(new
                {
                    ClaimId = context.Saga.ClaimId,
                    ServiceCode = context.Message.Data.ServiceCode
                })));

        CompositeEvent(() => AllVerificationsCompleted,
            x => x.VerificationStatus,
            EligibilityVerified, FraudCheckCompleted, PriorAuthVerified);

        During(VerifyingEligibility,
            When(AllVerificationsCompleted)
                .Then(context =>
                {
                    var isEligible = context.Saga.IsEligibilityVerified;
                    var isFraudClean = !context.Saga.IsFraudulent;
                    var isPriorAuthValid = context.Saga.IsPriorAuthValid;

                    context.Saga.CanAdjudicate = isEligible && isFraudClean && isPriorAuthValid;
                })
                .IfElse(context => context.Saga.CanAdjudicate,
                    approvedBinder => approvedBinder
                        .TransitionTo(Adjudicating)
                        .PublishAsync(context => context.Init<AdjudicateClaimCommand>(new
                        {
                            ClaimId = context.Saga.ClaimId
                        })),
                    rejectedBinder => rejectedBinder
                        .TransitionTo(Rejected)
                        .PublishAsync(context => context.Init<ClaimRejectedEvent>(new
                        {
                            ClaimId = context.Saga.ClaimId,
                            RejectionReasons = context.Saga.RejectionReasons
                        }))));

        During(Adjudicating,
            When(ClaimAdjudicated)
                .TransitionTo(Completed)
                .PublishAsync(context => context.Init<ClaimProcessingCompletedEvent>(new
                {
                    ClaimId = context.Saga.ClaimId,
                    ProcessedAt = DateTime.UtcNow
                }))
                .Finalize());

        SetCompletedWhenFinalized();
    }

    public State VerifyingEligibility { get; private set; }
    public State Adjudicating { get; private set; }
    public State Completed { get; private set; }
    public State Rejected { get; private set; }

    public Event<ClaimSubmittedEvent> ClaimSubmitted { get; private set; }
    public Event<EligibilityVerifiedEvent> EligibilityVerified { get; private set; }
    public Event<FraudCheckCompletedEvent> FraudCheckCompleted { get; private set; }
    public Event<PriorAuthVerifiedEvent> PriorAuthVerified { get; private set; }
    public Event AllVerificationsCompleted { get; private set; }
    public Event<ClaimAdjudicatedEvent> ClaimAdjudicated { get; private set; }
}

public class ClaimSagaState : SagaStateMachineInstance
{
    public Guid CorrelationId { get; set; }
    public string CurrentState { get; set; }
    public string ClaimId { get; set; }
    public DateTime SubmittedAt { get; set; }
    public int VerificationStatus { get; set; }
    public bool IsEligibilityVerified { get; set; }
    public bool IsFraudulent { get; set; }
    public bool IsPriorAuthValid { get; set; }
    public bool CanAdjudicate { get; set; }
    public List<string> RejectionReasons { get; set; } = new();
}
