// Health check for consumer status
public class EventConsumerHealthCheck : IHealthCheck
{
    private readonly IConsumerControl _consumerControl;

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        var consumerStatus = await _consumerControl.GetStatusAsync();

        if (!consumerStatus.IsRunning)
            return HealthCheckResult.Unhealthy(\"Consumer is not running\");

        if (consumerStatus.Lag > 10000)
            return HealthCheckResult.Degraded($\"Consumer lag is {consumerStatus.Lag}\");

        return HealthCheckResult.Healthy(\"Consumer is healthy\");
    }
}
