public class DeadLetterQueueProcessor : IHostedService
{
    private readonly IDeadLetterRepository _repository;
    private readonly IEventPublisher _publisher;

    // Process dead letter queue manually after investigation
    public async Task ReplayDeadLetterAsync(string deadLetterId)
    {
        var deadLetter = await _repository.GetAsync(deadLetterId);

        // Fix any data issues if needed
        var correctedEvent = ApplyCorrections(deadLetter.OriginalEvent);

        // Republish to original topic
        await _publisher.PublishAsync(
            deadLetter.OriginalTopic,
            correctedEvent,
            deadLetter.PartitionKey);

        // Mark as replayed
        await _repository.MarkReplayedAsync(deadLetterId);
    }
}
