### Real-World Example 1: Claims Processing Event Flow

**Context**: A state Medicaid claims processing system using synchronous architecture suffered cascading failures when dependent services were slow or down.

**Implementation**:

```csharp
// Event-driven claims workflow
public class ClaimsProcessingWorkflow
{
    // Step 1: Claims API publishes event (non-blocking)
    public async Task<IActionResult> SubmitClaim(ClaimRequest request)
    {
        var claim = await _repository.SaveAsync(Claim.Create(request));

        await _eventBus.Publish(new ClaimSubmittedEvent
        {
            Data = new ClaimData
            {
                ClaimId = claim.Id,
                ProviderId = request.ProviderId,
                MemberId = request.MemberId,
                ServiceDate = request.ServiceDate,
                BilledAmount = request.BilledAmount,
                State = "FL"
            }
        });

        // Return immediately - async processing continues
        return Accepted(new { claimId = claim.Id });
    }
}

// Step 2: Multiple services process event independently
public class EligibilityConsumer : IConsumer<ClaimSubmittedEvent>
{
    public async Task Consume(ConsumeContext<ClaimSubmittedEvent> context)
    {
        var result = await _eligibilityService.CheckAsync(
            context.Message.Data.MemberId,
            context.Message.Data.ServiceDate);

        await context.Publish(new EligibilityVerifiedEvent
        {
            ClaimId = context.Message.Data.ClaimId,
            IsEligible = result.IsEligible,
            CoverageType = result.CoverageType
        });
    }
}

public class FraudDetectionConsumer : IConsumer<ClaimSubmittedEvent>
{
    public async Task Consume(ConsumeContext<ClaimSubmittedEvent> context)
    {
        var fraudScore = await _fraudEngine.AnalyzeAsync(context.Message.Data);

        await context.Publish(new FraudCheckCompletedEvent
        {
            ClaimId = context.Message.Data.ClaimId,
            FraudScore = fraudScore,
            IsSuspicious = fraudScore > 0.75
        });
    }
}

// Step 3: Saga coordinates workflow
public class ClaimAdjudicationSaga : MassTransitStateMachine<ClaimSagaState>
{
    public ClaimAdjudicationSaga()
    {
        // Wait for eligibility AND fraud check completion
        CompositeEvent(() => ReadyForAdjudication,
            x => x.Status,
            EligibilityVerified, FraudCheckCompleted);

        During(Processing,
            When(ReadyForAdjudication)
                .IfElse(context => context.Saga.CanProcess,
                    approve => approve.PublishAsync(context =>
                        context.Init<AdjudicateClaimCommand>(new
                        {
                            ClaimId = context.Saga.ClaimId
                        })),
                    reject => reject.PublishAsync(context =>
                        context.Init<RejectClaimCommand>(new
                        {
                            ClaimId = context.Saga.ClaimId,
                            Reasons = context.Saga.RejectionReasons
                        }))));
    }
}
```

**Outcome**:
- **Response Time**: Claim submission API response times improve significantly through asynchronous processing
- **Resilience**: Eligibility service outages no longer impact claim submissions; events queue and process when service recovers
- **Independent Scaling**: Fraud detection scaled to 50 instances during peak; eligibility service remained at 10 instances
- **Event Replay**: Claims replayed through updated fraud algorithm after bug fix; impossible with synchronous architecture
- **Provider Satisfaction**: Providers appreciate faster claim submission responses with fewer timeout errors

